DONE_SENTINEL = "[DONE]"
_CONTENT_KEYS = {"content"}
_TERMINAL_KEYS = {"finish_reason", "completion_tokens"}
_FINISH_REASONS = ("length", "stop")


def _fail(reason):
    return {"success": False, "reason": reason}


def _is_plain_int(value):
    # bool is a subclass of int; boolean counts are invalid.
    return type(value) is int


def _is_done(frame):
    return isinstance(frame, str) and frame == DONE_SENTINEL


def _same_keys(frame, expected):
    if len(frame) != len(expected):
        return False
    for key in frame:
        if not isinstance(key, str) or key not in expected:
            return False
    return True


def evaluate(status, frames, requested_tokens):
    # 1. HTTP status gate.
    if not _is_plain_int(status) or status != 200:
        return _fail("http_error")

    # 2. Scan frames in order; the first failure wins.
    if not isinstance(frames, (list, tuple)):
        return _fail("malformed_frame")

    total = len(frames)
    terminal = None

    for index, frame in enumerate(frames):
        if _is_done(frame):
            # Only a single, final DONE is allowed. Any DONE that is not the
            # last frame is misplaced (this also covers duplicate DONE).
            if index != total - 1:
                return _fail("malformed_frame")
            continue

        if not isinstance(frame, dict):
            return _fail("malformed_frame")

        if "error" in frame:
            return _fail("stream_error")

        if _same_keys(frame, _CONTENT_KEYS):
            if not isinstance(frame["content"], str):
                return _fail("malformed_frame")
            if terminal is not None:
                # Content after the terminal frame.
                return _fail("malformed_frame")
            continue

        if _same_keys(frame, _TERMINAL_KEYS):
            finish_reason = frame["finish_reason"]
            completion_tokens = frame["completion_tokens"]
            if not isinstance(finish_reason, str) or finish_reason not in _FINISH_REASONS:
                return _fail("malformed_frame")
            if not _is_plain_int(completion_tokens) or completion_tokens < 0:
                return _fail("malformed_frame")
            if terminal is not None:
                # Duplicate terminal.
                return _fail("malformed_frame")
            terminal = (finish_reason, completion_tokens)
            continue

        return _fail("malformed_frame")

    # 3. A terminal is required (DONE alone is not a terminal).
    if terminal is None:
        return _fail("missing_terminal")

    finish_reason, completion_tokens = terminal

    # 4. Token accounting; fail closed on an invalid requested count.
    if not _is_plain_int(requested_tokens) or requested_tokens <= 0:
        return _fail("token_mismatch")

    if finish_reason == "length":
        if completion_tokens != requested_tokens:
            return _fail("token_mismatch")
        return {"success": True, "reason": "length"}

    if finish_reason == "stop":
        if completion_tokens > requested_tokens:
            return _fail("token_mismatch")
        return {"success": True, "reason": "stop"}

    return _fail("malformed_frame")

_DONE = "[DONE]"
_CONTENT_KEYS = {"content"}
_TERMINAL_KEYS = {"finish_reason", "completion_tokens"}
_FINISH_REASONS = ("length", "stop")


def _fail(reason):
    return {"success": False, "reason": reason}


def _is_int(value):
    # Booleans are a subclass of int in Python but are never valid counts/statuses.
    return isinstance(value, int) and not isinstance(value, bool)


def _is_done(frame):
    return isinstance(frame, str) and frame == _DONE


def evaluate(status, frames, requested_tokens):
    # 1. HTTP status gate: anything other than an integer 200 is an HTTP error.
    if not _is_int(status) or status != 200:
        return _fail("http_error")

    # Frames must be an ordered sequence of decoded frames.
    if not isinstance(frames, (list, tuple)):
        return _fail("malformed_frame")

    total = len(frames)
    terminal = None

    # 2. Inspect frames in order; the first offending frame decides the reason.
    for index in range(total):
        frame = frames[index]

        if _is_done(frame):
            # Only a single, final DONE marker is allowed. Any DONE that is
            # not the last frame is misplaced (this also covers duplicates).
            if index != total - 1:
                return _fail("malformed_frame")
            continue

        if not isinstance(frame, dict):
            return _fail("malformed_frame")

        # An error frame inside an HTTP-200 stream is a stream error, never success.
        if "error" in frame:
            return _fail("stream_error")

        keys = set(frame.keys())

        if keys == _CONTENT_KEYS:
            if not isinstance(frame["content"], str):
                return _fail("malformed_frame")
            if terminal is not None:
                # Content after the terminal frame.
                return _fail("malformed_frame")
            continue

        if keys == _TERMINAL_KEYS:
            finish_reason = frame["finish_reason"]
            count = frame["completion_tokens"]
            if not isinstance(finish_reason, str) or finish_reason not in _FINISH_REASONS:
                return _fail("malformed_frame")
            if not _is_int(count) or count < 0:
                return _fail("malformed_frame")
            if terminal is not None:
                # Duplicate terminal.
                return _fail("malformed_frame")
            terminal = (str(finish_reason), count)
            continue

        # Unknown, missing or extra fields.
        return _fail("malformed_frame")

    # 3. A terminal is required; DONE alone does not count as a terminal.
    if terminal is None:
        return _fail("missing_terminal")

    finish_reason, count = terminal

    # 4. Token accounting against the requested count (fail closed on a bad request count).
    if not _is_int(requested_tokens) or requested_tokens <= 0:
        return _fail("token_mismatch")

    if finish_reason == "length":
        if count != requested_tokens:
            return _fail("token_mismatch")
        return {"success": True, "reason": "length"}

    # finish_reason == "stop"
    if count > requested_tokens:
        return _fail("token_mismatch")
    return {"success": True, "reason": "stop"}
